  describe("getSentSnapshotData", () => {
    // The real typechain interfaces, so the two genuinely different `sendSnapshot`
    // signatures are exercised rather than a hand-rolled ABI that could be wrong
    // in the same way the code under test was.
    const arbToEthInterface = VeaInboxArbToEth__factory.createInterface();
    const arbToGnosisInterface = VeaInboxArbToGnosis__factory.createInterface();
    const epoch = 1;
    const gasLimit = 1_000_000;

    const claim: ClaimStruct = {
      stateRoot: "0xeac817ed5c5b3d1c2c548f231b7cf9a0dfd174059f450ec6f0805acf6a16a551",
      claimer: "0xFa00D29d378EDC57AA1006946F0fc6230a5E3288",
      timestampClaimed: 1730276784,
      timestampVerification: 1730276800,
      blocknumberVerification: 7654321,
      honest: 1,
      challenger: "0x1234567890123456789012345678901234567890",
    };

    const providerServing = (data: string | null) =>
      ({
        getTransaction: jest.fn(async () => (data === null ? null : { data })),
      }) as any;

    it("reads the claim from the 2-arg arbToEth sendSnapshot(epoch, claim)", async () => {
      const data = arbToEthInterface.encodeFunctionData("sendSnapshot", [epoch, claim]);

      const hash = await getSentSnapshotData("0x1234", providerServing(data), arbToEthInterface);

      expect(hash).toEqual(hashClaim(claim));
    });

    it("reads the claim from the 3-arg arbToGnosis sendSnapshot(epoch, gasLimit, claim)", async () => {
      const data = arbToGnosisInterface.encodeFunctionData("sendSnapshot", [epoch, gasLimit, claim]);

      const hash = await getSentSnapshotData("0x1234", providerServing(data), arbToGnosisInterface);

      // Reading args[1] here hashes the gas limit, so the hash never matches the
      // outbox's and an already-sent snapshot looks unsent forever.
      expect(hash).toEqual(hashClaim(claim));
    });

    it("does not let the arbToGnosis gas limit influence the claim hash", async () => {
      const dataA = arbToGnosisInterface.encodeFunctionData("sendSnapshot", [epoch, gasLimit, claim]);
      const dataB = arbToGnosisInterface.encodeFunctionData("sendSnapshot", [epoch, gasLimit * 2, claim]);

      const hashA = await getSentSnapshotData("0x1234", providerServing(dataA), arbToGnosisInterface);
      const hashB = await getSentSnapshotData("0x1234", providerServing(dataB), arbToGnosisInterface);

      expect(hashA).toEqual(hashB);
      expect(hashA).toEqual(hashClaim(claim));
    });

    it("hashes a different claim to a different hash on both routes", async () => {
      const otherClaim: ClaimStruct = { ...claim, honest: 2 };
      const ethData = arbToEthInterface.encodeFunctionData("sendSnapshot", [epoch, otherClaim]);
      const gnosisData = arbToGnosisInterface.encodeFunctionData("sendSnapshot", [epoch, gasLimit, otherClaim]);

      const ethHash = await getSentSnapshotData("0x1234", providerServing(ethData), arbToEthInterface);
      const gnosisHash = await getSentSnapshotData("0x1234", providerServing(gnosisData), arbToGnosisInterface);

      expect(ethHash).toEqual(hashClaim(otherClaim));
      expect(gnosisHash).toEqual(hashClaim(otherClaim));
      expect(ethHash).not.toEqual(hashClaim(claim));
    });

    it("returns null when the transaction cannot be fetched", async () => {
      const hash = await getSentSnapshotData("0x1234", providerServing(null), arbToEthInterface);

      expect(hash).toBeNull();
    });

    it("returns null instead of throwing when the calldata is not a sendSnapshot call", async () => {
      // `sendSnapshot` is cheap to spam with arbitrary data; an unparsable tx must
      // degrade to "not sent", never kill the route task.
      const data = arbToEthInterface.encodeFunctionData("saveSnapshot", []);

      const hash = await getSentSnapshotData("0x1234", providerServing(data), arbToGnosisInterface);

      expect(hash).toBeNull();
    });
  });
});

