363	/**
364	 * Locate the `Claim` argument in a parsed `sendSnapshot` call.
365	 *
366	 * The argument list is route-dependent:
367	 *   arbToEth              `sendSnapshot(uint256 _epoch, Claim _claim)`
368	 *   arbToGnosis/gnosisToArb `sendSnapshot(uint256 _epoch, uint256 _gasLimit, Claim _claim)`
369	 *
370	 * so a hardcoded index is wrong on one of them. The claim is the only
371	 * tuple-typed parameter in every variant, so the index is derived from the
372	 * parsed function fragment rather than from the route - no chainId plumbing,
373	 * and a future signature change cannot silently reintroduce the bug.
374	 *
375	 * @returns The index of the tuple parameter, or -1 if the fragment has none
376	 */
377	const claimArgIndex = (fragment: any): number => {
378	  const inputs = fragment?.inputs ?? [];
379	  // Searched from the end: the claim is always the last parameter.
380	  for (let i = inputs.length - 1; i >= 0; i--) {
381	    const input = inputs[i];
382	    if (input?.baseType === "tuple" || input?.type === "tuple") return i;
383	  }
384	  return -1;
385	};
386	
387	/**
388	 * Recompute the claim hash carried by a `sendSnapshot` transaction.
389	 *
390	 * Reading the wrong argument hashes the gas limit instead of the claim, so the
391	 * result never matches the outbox's `claimHashes[epoch]` and a snapshot that was
392	 * in fact sent looks unsent forever - the challenger then keeps re-sending it.
393	 *
394	 * @returns The claim hash the transaction carries, or null if it cannot be read
395	 */
396	const getSentSnapshotData = async (
397	  txHash: string,
398	  provider: JsonRpcProvider,
399	  inboxInterface: any
400	): Promise<string | null> => {
401	  const tx = await provider.getTransaction(txHash);
402	  if (!tx) return null;
403	
404	  // Parse the transaction calldata to identify function + args
405	  const parsed = inboxInterface.parseTransaction({ data: tx.data });
406	  // ethers v6 returns null for calldata no fragment matches; never throw here,
407	  // an unparsable tx is a "not sent" answer, not a dead route task.
408	  if (!parsed) return null;
409	  const index = claimArgIndex(parsed.fragment);
410	  if (index === -1) return null;
411	  const claimTuple = parsed.args[index] as unknown as ClaimStruct;
412	  const expectedClaimHash = hashClaim(claimTuple);
413	  return expectedClaimHash;
414	};
